def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    return np.where(remaining_space >= 0, -remaining_space, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    feasible = bins >= item
    diff = np.abs(bins - 2 * item)
    return np.where(feasible, -diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    count = np.floor_divide(bins, item)
    return np.where(bins >= item, count, -np.inf)
